spawn.example:
const { Vfx } = kcds.world;
const { Vector3 } = kcds.math;

const glow = Vfx.spawn('WH_Particels.other.magic', new Vector3(100, 200, 10), { scale: 2 });
glow.strength = 0.5;

// A flame over a player's right hand.
Vfx.spawn('cinematics.fires.fire_torch_refr', new Vector3(0, 0, 0.45), {
  entity: player,
  joint: 'RightHand',
});

spawn.exampleCs:
var glow = Vfx.Spawn("WH_Particels.other.magic", new Vector3(100, 200, 10), new { scale = 2 });
glow.Strength = 0.5;

// A flame over a player's right hand.
Vfx.Spawn("cinematics.fires.fire_torch_refr", new Vector3(0, 0, 0.45), new { entity = player, joint = "RightHand" });

