attach.example:
// client
const { Vfx } = kcds.world;

const smoke = Vfx.attach(Vfx.list()[0], kcds.players.LocalPlayer, {
  offset: { x: 0, y: 0, z: 1 },
  durationMs: 5000,
});
Vfx.stop(smoke);

attach.exampleCs:
// client
var smoke = Vfx.Attach(Vfx.List()[0], LocalPlayer.Current, new
{
    offset = new { x = 0, y = 0, z = 1 },
    durationMs = 5000,
});
Vfx.Stop(smoke);

burstFrom.example:
const { Vfx } = kcds.world;
const { Vector3 } = kcds.math;

kcds.core.Events.on('playerLevelUp', (player) => {
  Vfx.burstFrom('WH_Particels.other.magic', player, { offset: new Vector3(0, 0, 2) });
});

// A flame on a torch held in the right hand, 40 cm up from the hand.
Vfx.burstFrom('WH_Particels.fires.torch_trailer', player, {
  joint: 'RightHand',
  offset: new Vector3(0, 0, 0.4),
  durationMs: 60000,
});

burstFrom.exampleCs:
Events.On("playerLevelUp", (Player player) =>
{
    Vfx.BurstFrom("WH_Particels.other.magic", player, new { offset = new Vector3(0, 0, 2) });
});

// A flame on a torch held in the right hand, 40 cm up from the hand.
Vfx.BurstFrom("WH_Particels.fires.torch_trailer", player, new { joint = "RightHand", offset = new Vector3(0, 0, 0.4), durationMs = 60000 });

